{
  "name": "@zyplux/cz",
  "version": "0.15.0",
  "description": "Repository helper CLI: PRs, workspace maintenance, reports and file chunking.",
  "keywords": [
    "cli",
    "monorepo",
    "automation",
    "github"
  ],
  "license": "MIT",
  "author": "Sergiy Yeskov <sergiy.yeskov@gmail.com>",
  "homepage": "https://github.com/zyplux/zyplux/tree/main/apps/cz",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/zyplux/zyplux.git",
    "directory": "apps/cz"
  },
  "type": "module",
  "bin": {
    "cz": "./src/index.ts"
  },
  "exports": {
    "./contracts": "./src/contracts.ts",
    "./package.json": "./package.json",
    "./cli": "./src/cli.ts"
  },
  "imports": {
    "#deps-catalog": "./src/deps-catalog.ts",
    "#optique": "./src/optique.ts",
    "#workspace-graph": "./src/workspace-graph.ts"
  },
  "files": [
    "README.md",
    "dist"
  ],
  "publishConfig": {
    "access": "public",
    "imports": {
      "#deps-catalog": "./dist/src/deps-catalog.js",
      "#optique": "./dist/src/optique.js",
      "#workspace-graph": "./dist/src/workspace-graph.js"
    },
    "bin": {
      "cz": "./dist/src/index.js"
    },
    "exports": {
      "./contracts": {
        "types": "./dist/src/contracts.d.ts",
        "default": "./dist/src/contracts.js"
      },
      "./package.json": "./package.json",
      "./cli": {
        "types": "./dist/src/cli.d.ts",
        "default": "./dist/src/cli.js"
      }
    }
  },
  "scripts": {
    "prepack": "node --eval \"require('node:fs').rmSync('dist', { force: true, recursive: true })\" && tsc -b --force tsconfig.json && publint --pack pnpm --strict"
  },
  "dependencies": {
    "@happy-dom/global-registrator": "catalog:",
