    "@optique/run": "catalog:",
    "@zyplux/util": "workspace:*",
    "commonmark": "catalog:",
    "mermaid": "catalog:",
    "zod": "catalog:",
    "typescript": "catalog:",
    "yaml": "catalog:"
  },
  "devDependencies": {
    "@types/commonmark": "catalog:",
    "@types/node": "catalog:",
    "@zyplux/tsconfig": "workspace:*",
    "publint": "catalog:"
  }
}

